from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import PaymentInstrument, CorporateCreditLine

class UpdateBillingLimitView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, instrument_id):
        new_limit = request.data.get('monthly_limit')
        try:
            instrument = PaymentInstrument.objects.get(id=instrument_id)
        except PaymentInstrument.DoesNotExist:
            return Response({'error': 'Instrument not found'}, status=status.HTTP_404_NOT_FOUND)

        if isinstance(instrument, CorporateCreditLine):
            # Enforce corporate financial officer permission for corporate lines
            if not request.user.has_perm('billing.can_modify_corporate_limits', instrument.company):
                return Response({'error': 'Only corporate financial signatories may modify credit line limits'}, status=status.HTTP_403_FORBIDDEN)
        elif instrument.registered_user != request.user:
            return Response({'error': 'Access denied'}, status=status.HTTP_403_FORBIDDEN)

        instrument.monthly_limit = new_limit
        instrument.save(update_fields=['monthly_limit'])
        return Response({'status': 'updated', 'monthly_limit': instrument.monthly_limit})
